function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',4500);}
function today(){return localDay();}function log(){return dayLog(state,today());}
function nav(to){route=to;location.hash=to;render();document.querySelector('main')?.focus();window.scrollTo({top:0,behavior:'instant'});}
window.addEventListener('hashchange',()=>{if(location.hash==='#main'){document.getElementById('main')?.focus();return;}route=location.hash.slice(1)||'ielts';render();});
function header(){const selected=route.startsWith('ielts')?'ielts':route==='learn'?'today':route;return `<header class="topbar"><a class="brand" href="#ielts"><span class="logo">L</span>词序 <small>Lexiday</small></a><nav aria-label="主导航">${[['ielts','雅思计划'],['grammar','语法课堂'],['today','单词学习'],['courses','词书课程'],['reading','今日阅读'],['quiz','听力测验'],['report','学习报告']].map(([id,label])=>`<a href="#${id}" ${selected===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span></a>`).join('')}</nav>${accountButton()}</header>`;}
function pageTitle(eyebrow,title,sub,action=''){return `<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="muted">${sub}</p></div>${action}</div>`;}
function progressBar(value,total){return `<div class="progress"><span style="width:${Math.min(100,total?value/total*100:0)}%"></span></div>`;}
const completedIn=c=>c.words.filter(id=>state.knownWords?.[id]||wordMap[id].senses.every(s=>state.records[s.id]?.level&&!state.records[s.id]?.pending)).length;
function todayPage(){const c=courseMap[state.course],stats=dailyStats(state),l=log(),count=plannedCount(state),q=state.session;const active=q?.day===today()&&q.stage!=='done';const allDone=q?.day===today()&&q.stage==='done';const left=remainingWords(state).length,days=Math.ceil(left/count);const current=active?courseMap[q.course]:c;
 return `${pageTitle('A LITTLE, EVERY DAY','今天，也向前一点。','让每个单词，从眼熟变成真正理解。',`<span class="date-label">${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</span>`)}<div class="dashboard"><div class="main-column"><section class="focus"><div><div class="focus-meta"><span class="pill">${active?'继续上次进度':'当前词书'}</span><span>${current.id.startsWith('ielts-')?'雅思 GT 精选词库':'示例词库'}</span></div><h2>${current.name}</h2><p>${active?'你的学习进度已经保存，接着上一次继续。':'优先完成到期听音复习，再学习新词。'}</p><div class="focus-progress"><span>词书进度 ${completedIn(current)} / ${current.words.length}</span>${progressBar(completedIn(current),current.words.length)}</div><button class="primary" data-action="start" ${state.plan.paused?'disabled':''}>${state.plan.paused?'计划已暂停':active?'继续学习':allDone&&stats.new>=count?'查看今日成果':'开始今日学习'} ${icon('arrow')}</button></div><div class="daily-target"><div class="ring" style="--p:${Math.min(100,stats.new/count*100)}%"><div><b>${String(Math.max(0,count-stats.new)).padStart(2,'0')}</b><span>待学新词</span></div></div><span>每日计划 ${count} 词</span></div></section><div class="stats-grid"><div class="stat"><span>${icon('courses')}今日新学</span><b>${stats.new}<small> / ${count} 词</small></b><p>按单词去重统计</p></div><div class="stat"><span>${icon('clock')}到期复习</span><b>${stats.due}<small> 个词义</small></b><p>先听音回想，再逐级提示</p></div><div class="stat"><span>${icon('check')}今日通过</span><b>${completedWords(state).length}<small> 词</small></b><p>已完成规定词义</p></div></div><section class="panel journey-panel"><div class="section-heading"><h2>今天的学习路径</h2><span class="muted">一步一步，记得更牢</span></div><div class="journey">${[['01','单词与语境','自测 · 详解 · 强化','today'],['02','读一篇短文','把今天的词串起来','reading'],['03','听力小测验','在声音中辨认词义','quiz']].map(([num,title,desc,id])=>`<button data-action="${id==='today'?'start':'navigate'}" data-to="${id}" class="journey-step"><span class="step-number">${num}</span><strong>${title}</strong><small>${desc}</small>${icon('arrow')}</button>`).join('')}</div></section><section class="panel group-preview"><div class="section-heading"><h2>有关联，也有区别</h2><span class="pill">对比记忆</span></div><div class="word-pair"><span>hinder<small>v. 阻碍</small></span><i>≠</i><span>hinge<small>n. 铰链</small></span></div><p class="muted">长得像，不一定意思相近。详解页会帮你看清每一处不同。</p></section></div><aside class="side-column"><section class="panel plan-card"><div class="section-heading"><h2>我的计划</h2><button class="icon-btn" data-action="plan" aria-label="调整学习计划">${icon('settings')}</button></div><div class="plan-count"><b>${count}</b><span>新词 / 天</span></div><div class="info-row"><span>当前词库</span><strong>${c.words.length} 词</strong></div><div class="info-row"><span>剩余新词</span><strong>${left} 词</strong></div><div class="info-row"><span>预计完成</span><strong>${left?projectedFinish(state):'已学完'}</strong></div><button class="full-width" data-action="plan">调整学习计划</button><button class="text-button full-width" data-action="pause">${state.plan.paused?'恢复学习计划':'暂停计划'}</button><p class="fine">${state.plan.paused?'计划已暂停，学习记录会保留。':'完成日期仅指新词学完，后续仍需复习。'}</p></section><section class="tip-card"><span class="mini-label">记忆小约定</span><h3>不认识，也没关系。</h3><p>一个词义没记住，就在不同轮次听音并输入正确释义 3 次。慢一点，记得久一点。</p><div class="three-dots"><span>1</span><i></i><span>2</span><i></i><span>3</span>${icon('check')}</div></section><p class="fine demo-note">演示模式 · 访客本机保存 · 登录后云端同步<br>自主整理 · 非官方完整词表</p></aside></div>`;
}
function coursesPage(){const items=courses.filter(c=>courseFilter==='全部'||c.level===courseFilter);return `${pageTitle('YOUR WORD LIBRARY','选一本，开始积累。','15 个学习方向，按你的阶段一步步来。')}<section class="panel vocabulary-banner"><span class="pill">词库更新 · 2026-10-30</span><h2>雅思基础：精选语境词 + 上传扩展词表</h2><p>导入 ${importedInfo.entries} 个去重词条，新增 ${importedInfo.added} 词，与原词库共享 ${importedInfo.overlap} 词。原有 220 词保留例句与学习记录。</p><p class="fine">${importedInfo.source}。词性、释义和例句分开呈现；新词需通过听音输入中文释义验证。</p><p class="fine">${vocabularyInfo.description} 分数还取决于搭配、语法、理解和表达能力。</p><div class="actions">${vocabularyInfo.sources.map(s=>`<a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title} ↗</a>`).join('')}</div></section><div class="toolbar"><div class="segmented" role="group" aria-label="课程级别">${['全部','基础','进阶','拓展'].map(f=>`<button data-action="filter" data-filter="${f}" class="${courseFilter===f?'active':''}">${f}</button>`).join('')}</div><span class="muted">${courses.filter(c=>c.words.length).length} 本可学习 · ${words.length} 个去重单词</span></div><div class="course-grid">${items.map((c)=>`<article class="course-card ${c.words.length?'':'unavailable'}"><div class="course-cover ${c.color}"><span>${c.label}</span><div>${c.name}</div><small>${c.level} / ${c.id.startsWith('ielts-')?'GT 精选版':c.words.length?'示例版':'筹备中'}</small></div><div class="course-body"><h2>${c.name}</h2><p>${c.audience}</p><div class="info-row"><span>${c.words.length} 个单词</span><span>${c.words.length?completedIn(c)+' / '+c.words.length+' 已学 / 熟知':'词库待补充'}</span></div>${progressBar(completedIn(c),c.words.length)}${c.words.length?`<button class="text-button full-width" data-action="vocabulary" data-id="${c.id}">查看词表与释义</button>`:""}<button class="full-width ${state.course===c.id?'primary':''}" data-action="course" data-id="${c.id}" ${!c.words.length?'disabled':''}>${!c.words.length?'暂未开放':state.course===c.id?'当前词书':'选择词书'}</button></div></article>`).join('')}</div><p class="fine">跨课程共享相同词义的学习记录。示例内容为原创教学材料，不代表官方收词范围。</p>`;}
function highlightWord(en,id,interactive=false,senseId=''){const re=new RegExp(`\\b(${id})\\b`,'gi');return esc(en).replace(re,interactive?`<button class="inline-word" data-action="gloss" data-id="${id}" data-sense="${senseId}">$1</button>`:'<mark>$1</mark>');}
function speakButton(text,label='播放发音',cls=''){return `<button class="sound-btn ${cls}" data-action="speak" data-text="${esc(text)}" aria-label="${label}">${icon('sound')}<span>${label}</span></button>`;}
function knownWordControl(w){return '<button class="known-word-button" data-action="exclude-known" data-id="'+esc(w.id)+'">完全记住 · 此词不再学习和复习</button><p class="fine">可在“学习报告 → 完全记住的词”中恢复。</p>';}
function meaningEntry(w,entry){
 const examples=entry.examples||[];
 return '<section class="meaning-row"><div class="meaning-entry-heading"><span class="pos">'+esc(entry.pos)+'</span><strong>'+esc(entry.meaning)+'</strong></div><div class="meaning-audio"><span class="phonetic">'+esc(entry.ipa||wordPronunciation(w))+'</span>'+speakButton(examples[0]?.en||spokenWord(w),'听此词义的语境发音','compact')+'</div>'+(entry.definition?'<p class="fine">'+esc(entry.definition)+'</p>':'')+examples.map(ex=>'<div class="sense-example"><p>'+esc(ex.en)+'</p><p class="muted">'+esc(ex.zh)+'</p>'+speakButton(ex.en,'朗读此例句','compact')+'</div>').join('')+(examples.length?'':'<p class="fine">此义项例句尚未补充。</p>')+'</section>';
}
function meaningForm(q,ready){return '<form id="meaning-answer-form" class="meaning-input-form"><label for="meaning-answer">输入你听到的单词的中文意思</label><input id="meaning-answer" name="meaning" maxlength="200" autocomplete="off" placeholder="输入中文释义，不提供选项" value="'+esc(q.listenDraft||'')+'" aria-describedby="meaning-input-help"><p class="fine" id="meaning-input-help">接受已收录的同义表述；不要填写英文拼写。先听完，再提交。</p><button type="submit" class="primary" id="meaning-submit" '+(ready?'':'disabled')+'>提交中文释义</button></form>';}
function listenCard(q,w,se,ex){return '<section class="panel recall-card listening-recall"><span class="pill">听音输入验证 · 第 '+q.current.round+' 轮</span><h2>听声音，写出中文意思。</h2><p class="muted">拼写、例句原文与中文释义已隐藏。</p><div class="actions"><button class="primary review-speaker" data-action="listen-play">'+icon('sound')+' 播放 / 重播</button><button data-action="listen-cue" data-cue="'+(q.listenCue==='word'?'context':'word')+'" '+(!ex&&q.listenCue==='word'?'disabled':'')+'>'+(q.listenCue==='word'?'改听带单词的例句':'只听单词')+'</button></div><p id="learning-audio-status" role="status">'+(q.listenPlayed?'已听完，可以输入中文释义。':'正在自动播放，请听完后输入。')+'</p>'+meaningForm(q,q.listenPlayed)+'<button class="text-button" data-action="listen-unknown">没听懂 / 不知道</button>'+(q.audioUnavailable?'<p class="warning">音频未完成播放，可点“播放 / 重播”重试；本次不会算作听音通过。</p>':'')+'</section>';}
function learnPage(){
 const q=state.session;
 if(!q||q.day!==today())return empty('今天的单词，准备好了。','先安排到期复习，再学习新词；听音输入中文后才能通过。','开始学习','start');
 if(q.stage==='done')return '<section class="completion panel"><div class="success-icon">'+icon('check')+'</div><div class="eyebrow">SESSION COMPLETE</div><h1>本轮学习已完成。</h1><p class="muted">未标记“完全记住”的词，仍会按计划复习。</p><div class="completion-stats"><span><b>'+log().newWords.length+'</b>新学单词</span><span><b>'+log().reviewWords.length+'</b>复习单词</span><span><b>'+log().passed.length+'</b>通过词义</span></div><div class="actions"><button class="primary" data-action="navigate" data-to="reading">阅读今日文章 '+icon('arrow')+'</button><button data-action="navigate" data-to="report">查看学习报告</button></div></section>';
 const t=q.current,w=wordMap[t.wordId],se=w.senses.find(s=>s.id===t.senseId),st=q.states[se.id],ex=activeExample(state),target=studyMeaning(w,se,ex);
 const total=Object.keys(q.states).length,passed=Object.values(q.states).filter(s=>s.passed).length,review=q.types[w.id]==='review';
 const steps=review?['听单词','听例句','文字辅助','核对释义']:['裸词自测','例句自测','单词详解','听音输入'];
 const stepIndex=review?['audio','context','spelling','sentence'].indexOf(q.cue):({bare:0,sentence:1,detail:2,listen:3,result:3}[q.stage]??-1);
 const top='<div class="learning-top"><a href="#today">‹ 返回今日学习</a><span>'+courseMap[q.course].name+' · '+(review?'到期复习':'新词学习')+'</span><span>'+passed+' / '+total+' 词义通过</span></div>'+progressBar(passed,total)+'<div class="learning-layout"><div class="learning-main"><div class="learning-steps">'+steps.map((name,i)=>'<span class="'+(i===stepIndex?'current':'')+'">'+(i+1)+' '+name+'</span>').join('<i></i>')+'</div>';
 const side='</div><aside class="learning-side"><section class="panel"><span class="mini-label">'+((!review&&st.strong)?'强化记忆':'听音验证')+'</span><h3>'+((!review&&st.strong)?'在不同轮次听懂它。':'听懂，再输入。')+'</h3>'+((!review&&st.strong)?'<div class="recognition-dots">'+[1,2,3].map(i=>'<span class="'+(st.known>=i?'filled':'')+'">'+(st.known>=i?'✓':i)+'</span>').join('')+'</div><p>当前 '+st.known+' / 3 次听音输入正确。</p>':'<p>“认识”和查看详解只用于学习，不直接算通过。</p>')+'<p class="fine">答错会再次学习例句并重新听音。输入草稿和进度自动保存。</p><button data-action="known-list">管理完全记住的词</button></section></aside></div>';
 let body='';
 if(q.stage==='review')body=reviewCard(q,w,se,ex);
 if(q.stage==='rest'){
  const sec=Math.max(0,Math.ceil((q.readyAt-Date.now())/1000));
  body='<section class="panel recall-card"><span class="pill">稍后再回想</span><h2>稍停一下，再看另一条例句。</h2><p class="muted">接下来会重新展示并朗读例句，再进行听音输入验证。</p><button class="primary" data-action="rest" id="rest-button" '+(sec?'disabled':'')+'>'+(sec?'稍后继续 · '+sec+' 秒':'进入下一轮')+'</button></section>';
  clearInterval(restTimer);restTimer=setInterval(()=>{const button=document.getElementById('rest-button');if(!button){clearInterval(restTimer);return;}const seconds=Math.max(0,Math.ceil((q.readyAt-Date.now())/1000));button.disabled=!!seconds;button.textContent=seconds?'稍后继续 · '+seconds+' 秒':'进入下一轮';if(!seconds)clearInterval(restTimer);},300);
 }
 if(q.stage==='bare')body='<section class="panel recall-card"><span class="pill">裸词自测 · 自动朗读</span><div class="bare-word">'+esc(w.word)+'</div><div class="phonetic">'+esc(wordPronunciation(w))+' '+speakButton(spokenWord(w),'再听单词','compact')+'</div><p class="question-prompt">先凭印象回想这个词。</p><div class="answer-buttons"><button data-action="bare-no"><span>还不认识</span><small>接下来学习例句</small></button><button class="primary" data-action="bare-yes"><span>有印象</span><small>用例句核对，稍后听音输入</small></button></div></section>';
 if(q.stage==='sentence')body='<section class="panel recall-card"><span class="pill">'+(t.round>1?'重新学习 · 另一条例句':'例句自测 · 自动朗读')+'</span><div class="sentence-word">'+esc(w.word)+' <span>'+esc(target.ipa||se.ipa||wordPronunciation(w))+'</span></div>'+(ex?'<p class="example-sentence">'+highlightWord(ex.en,w.id)+'</p>'+speakButton(ex.en,'再听例句'):'<p class="warning">此词的语境材料尚未加载。</p>')+'<p class="question-prompt">你能回想它在例句里的意思吗？</p><div class="answer-buttons"><button data-action="sense-no"><span>还不理解</span><small>查看详解并强化</small></button><button class="primary" data-action="sense-yes"><span>查看详解核对</span><small>之后仍需听音输入验证</small></button></div></section>';
 if(q.stage==='detail')body='<section class="panel detail-card"><div class="detail-heading"><div><span class="eyebrow">WORD IN CONTEXT</span><h1>'+esc(w.word)+'</h1><span class="muted">'+esc(target.ipa||se.ipa||wordPronunciation(w))+'</span></div>'+speakButton(spokenWord(w),'再听单词','compact')+'</div><div class="tested-meaning"><span class="mini-label">本次学习的词义</span><h2><span class="pos">'+esc(target.pos)+'</span>'+esc(target.meaning)+'</h2>'+(ex?'<p class="detail-example">'+highlightWord(ex.en,w.id)+'</p><p class="muted">'+esc(ex.zh)+'</p>'+speakButton(ex.en,'再听本轮例句'):'')+(review?'<p class="review-result">'+reviewGrades[q.reviewGrade??0].label+(st.passed?' · 本次已通过':' · 尚未通过听音，明天继续')+'</p>':'<p class="fine">这里会自动读出单词和例句，下一步将隐藏文字，输入中文释义。</p>')+'</div><h2>不同词性与词义</h2>'+wordEntries(w).map(entry=>meaningEntry(w,entry)).join('')+'<section class="word-notes"><div class="section-heading"><h2>单词笔记</h2><span class="pill">每个关联词只显示一次</span></div>'+relationCards(w)+'</section><div class="detail-footer"><p class="fine">'+(review?'文字辅助不替代首次听音验证。':'查看详解不会增加通过次数。')+'</p><button class="primary" data-action="continue">'+(review?'继续学习':'开始听音输入验证')+' '+icon('arrow')+'</button></div></section>';
 if(q.stage==='listen')body=listenCard(q,w,se,ex);
 if(q.stage==='result')body='<section class="panel detail-card"><span class="pill">听音输入结果</span><h1>'+(q.listenVerdict.correct?'本轮输入正确':'这次还没有答对')+'</h1><p>你的输入：<strong>'+esc(q.listenVerdict.input||'没听懂 / 不知道')+'</strong></p><h2>'+esc(w.word)+'</h2><p class="mini-label">本轮例句中的释义</p><p><span class="pos">'+esc(target.pos)+'</span>'+esc(target.meaning)+'</p>'+(ex?'<p>'+esc(ex.en)+'</p><p class="muted">'+esc(ex.zh)+'</p>'+speakButton(ex.en,'再听本轮例句'):'')+'<p class="'+(q.listenVerdict.correct?'correct-text':'wrong-text')+'">'+(st.passed?'此词义已通过听音输入验证，将按计划复习。':st.strong?'当前 '+st.known+' / 3 次有效听音输入，稍后换例句再来。':'稍后重新学习并验证。')+'</p><button class="primary" data-action="continue">继续学习 '+icon('arrow')+'</button></section>';
 return top+body+knownWordControl(w)+side;
}
function empty(title,sub,label,action,to=''){return `<section class="panel empty-state"><div class="empty-icon">${icon(route==='reading'?'reading':route==='quiz'?'quiz':'courses')}</div><h1>${title}</h1><p class="muted">${sub}</p><button class="primary" data-action="${action}" data-to="${to}">${label} ${icon('arrow')}</button></section>`;}
function readyForExtras(){return log().touched.length&&state.session?.day===today()&&state.session.stage==='done';}
function articleParagraph(en,glossary,paragraphIndex){
 const candidates=glossary.flatMap(g=>wordForms(g.wordId).map(form=>({form,g}))).sort((a,b)=>b.form.length-a.form.length);
 if(!candidates.length)return esc(en);
 const pattern=new RegExp(`(?<![A-Za-z])(?:${[...new Set(candidates.map(x=>escapeRegExp(x.form)))].join('|')})(?![A-Za-z])`,'gi');
 let result='',last=0;for(const match of en.matchAll(pattern)){const g=candidates.find(x=>x.form.toLowerCase()===match[0].toLowerCase()).g;result+=esc(en.slice(last,match.index))+`<button class="inline-word" data-action="gloss" data-id="${esc(g.wordId)}" data-sense="${esc(g.senseId)}" data-paragraph="${paragraphIndex}">${esc(match[0])}</button>`;last=match.index+match[0].length;}return result+esc(en.slice(last));
}
async function generateDailyArticle(){
 if(articleLoading||!readyForExtras())return;
 const owner=state,day=today(),dayRecord=log(),ids=[...dayRecord.touched],senseIds=[...dayRecord.passed];
 articleLoading=true;articleNotice='';render();
 let article;
 try{
  const response=await fetch('/api/reading',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids,senseIds}),signal:AbortSignal.timeout(90000)});
  const result=await response.json();if(!response.ok)throw Object.assign(Error(result.error||'暂时无法生成今日专属文章。'),{status:response.status});
  article=validateReadingArticle(result.article);
 }catch(error){
  article=createArticle(ids,senseIds);
  articleNotice=error.status===429?'今日文章生成额度已用完，先读这篇完整主题文章，明天再生成。':'今日专属文章暂未生成，先读这篇完整主题文章；稍后可重试。';
 }
 finally{articleLoading=false;}
 if(state===owner&&today()===day&&JSON.stringify(dayRecord.touched)===JSON.stringify(ids)){dayRecord.article=article;selectedWord=null;save();}
 if(route==='reading')render();
}
function readingPage(){
 if(!readyForExtras())return empty('先积累，再读懂一段故事。','完成今日卡片任务后，这里会出现包含今日单词的英文短文。','去完成今日学习','start');
 const saved=log().article,a=saved?.version===READING_VERSION?saved:null;
 if(!a)return `${pageTitle('WORDS BECOME A STORY','把今天的词，放进故事里。','围绕一个主题，读完有开头、发展和结尾的完整文章。')}<section class="panel empty-state">${icon('reading','large-icon')}<h2>${log().touched.length} 个单词，一篇连贯文章。</h2><p class="muted">根据今日词汇组织故事和段落，按需要扩充篇幅；可以查看逐段译文，点击文中单词复习。</p><button class="primary" data-action="article" ${articleLoading?'disabled':''}>${articleLoading?'正在组织情节与段落…':'生成今日阅读'} ${icon('arrow')}</button>${articleLoading?'<p class="fine" role="status">正在写作和检查文章，完成后会自动保存。</p>':''}</section>`;
 const matched=selectedWord&&a.glossary.find(g=>g.wordId===selectedWord.wordId&&g.senseId===selectedWord.senseId),selectedParagraph=matched&&a.paragraphs[Number.isInteger(selectedWord.paragraphIndex)?selectedWord.paragraphIndex:matched.paragraphIndex],chosen=matched&&{...matched,...selectedParagraph},chosenWord=chosen&&wordMap[chosen.wordId];
 return `${pageTitle('DAILY READING','今天的词，今天的故事。','顺着文章的情节和思路，在完整语境中重温单词。')}<div class="reading-layout"><article class="panel article"><div class="article-tools"><span class="pill">${a.mode==='generated'?'今日专属文章':'完整主题文章'}</span><div><button data-action="toggle-highlight" aria-pressed="${highlight}">高亮${highlight?'开':'关'}</button><button data-action="translation" aria-pressed="${translation}">${translation?'隐藏':'显示'}译文</button></div></div><div class="eyebrow">THE DAILY NOTEBOOK</div><h1>${esc(a.title)}</h1><p class="muted">${esc(a.subtitle)}</p><div class="reading-meta"><span>${a.wordCount} 词 · 约 ${Math.max(2,Math.ceil(a.wordCount/120))} 分钟</span><span>覆盖今日 ${a.covered}/${a.total} 词</span>${speakButton(a.paragraphs.map(p=>p.en).join(' '),'全文朗读')}<button class="text-button" data-action="stop-speech">停止</button></div>${articleNotice?`<p class="fine" role="status">${esc(articleNotice)}</p>`:''}<div class="article-body ${highlight?'':'no-highlight'}">${a.paragraphs.map((p,i)=>`<p>${articleParagraph(p.en,a.glossary.filter(g=>g.paragraphIndex===i||wordForms(g.wordId).some(form=>new RegExp('(?<![A-Za-z])'+escapeRegExp(form)+'(?![A-Za-z])','i').test(p.en))),i)}</p>${translation?`<p class="translation">${esc(p.zh)}</p>`:''}`).join('')}</div><div class="detail-footer"><p class="fine">以文章通顺为先；覆盖数只统计正文中实际出现的今日词汇。</p><button class="primary" data-action="navigate" data-to="quiz">进入听力测验 ${icon('arrow')}</button>${a.mode==='library'?`<button data-action="article" ${articleLoading?'disabled':''}>${articleLoading?'正在组织今日文章…':'生成今日专属文章'}</button>`:''}</div></article><aside><section class="panel glossary"><h2>${chosen?esc(chosen.wordId):'阅读词卡'}</h2>${chosen?`${chosen.dictionaryGloss?'<p class="fine">词典释义参考 · 请结合本段理解</p>'+wordEntries(chosenWord).map(entry=>'<p><span class="pos">'+esc(entry.pos)+'</span> '+esc(entry.meaning)+'</p>').join(''):'<span class="pos">'+esc(chosen.pos)+'</span><h3>'+esc(chosen.meaning)+'</h3>'}<p>${esc(chosen.en)}</p><p class="muted">${esc(chosen.zh)}</p>${speakButton(spokenWord(chosenWord),'听发音')}${speakButton(chosen.en,'朗读所在段落')}`:'<p class="muted">点击文章中的目标词，在这里查看词义和所在段落。</p>'}</section><section class="panel coverage-panel"><h3>文中遇见的今日单词</h3><div class="word-chips">${a.glossary.map(g=>`<button data-action="gloss" data-id="${esc(g.wordId)}" data-sense="${esc(g.senseId)}">${esc(g.wordId)} <span>✓</span></button>`).join('')||'<p class="muted">这篇主题文章没有包含今日目标词，可重试生成专属文章。</p>'}</div>${a.missing.length?`<details><summary>本篇未出现的 ${a.missing.length} 个词</summary><p class="fine">${a.missing.map(esc).join('、')}</p></details>`:''}</section></aside></div>`;
}

function quizPage(){if(!readyForExtras())return empty('用耳朵，再认识一次。','先完成今日卡片学习，再用听力检验词义理解。','去完成今日学习','start');const quiz=log().quiz;if(!quiz)return empty('准备好，听一听。','每次最多 10 题，优先测试薄弱词义。使用设备英文语音，不需要 API。','开始听力测验','quiz-start');
 if(quiz.index>=quiz.questions.length){const correct=quiz.answers.filter(a=>a.correct).length,assisted=quiz.answers.filter(a=>a.assisted).length;return `<section class="panel completion"><div class="success-icon">${icon('quiz')}</div><div class="eyebrow">LISTENING COMPLETE</div><h1>每次听懂，都是进步。</h1><div class="score">${Math.round(correct/quiz.questions.length*100)}<small>%</small></div><p class="muted">答对 ${correct} / ${quiz.questions.length} 题 · 原文辅助 ${assisted} 题</p><div class="actions"><button class="primary" data-action="navigate" data-to="report">查看学习报告</button>${correct<quiz.questions.length?'<button data-action="quiz-wrong">当天错题加练</button>':''}</div><div class="quiz-review">${quiz.answers.map((a,i)=>`<div class="review-row"><span class="${a.correct?'correct-text':'wrong-text'}">${a.correct?'✓':'×'}</span><strong>${quiz.questions[i].wordId}</strong><span>${quiz.questions[i].meaning}</span><small>${a.assisted?'使用原文辅助':''}</small></div>`).join('')}</div><p class="fine">错题词义已安排明日复习。当天通过的词不会自动重新刷卡。</p></section>`;}
 const question=quiz.questions[quiz.index],answer=quiz.answers[quiz.index];return `${pageTitle('LISTEN & UNDERSTAND','听懂句子里的那个词。','根据语境，选择它在这句话中的意思。')}<div class="quiz-container"><div class="quiz-heading"><span>第 ${quiz.index+1} / ${quiz.questions.length} 题</span><span class="pill">设备语音 · 演示题库</span></div>${progressBar(quiz.index,quiz.questions.length)}<section class="panel quiz-card"><button class="listen-orb" data-action="quiz-play" aria-label="重播音频">${icon('sound')}</button><p class="muted" id="quiz-audio-status" role="status">${quizAudioStatus(quiz)}</p><h2>${quiz.submitted?'对照原文，再听一遍。':'听句子和语音问题，选择对应的意思。'}</h2><button class="text-button" data-action="reveal" ${quiz.revealed||quiz.submitted?'disabled':''}>${quiz.revealed?'已使用原文辅助':quiz.submitted?'已显示原文':'显示原文（记录为辅助作答）'}</button>${quiz.revealed||quiz.submitted?`<p class="quiz-transcript">${highlightWord(question.en,question.wordId)}</p>`:''}<div class="options">${question.options.map((option,i)=>`<button data-action="option" data-index="${i}" ${quiz.submitted||(!quiz.played&&!quiz.revealed)?'disabled':''} class="${quiz.submitted?(option===question.meaning?'correct':answer.chosen===option?'incorrect':''):''}"><span>${'ABCD'[i]}</span>${option}${quiz.submitted&&option===question.meaning?icon('check'):''}</button>`).join('')}</div>${quiz.submitted?`<div class="answer-explanation"><strong class="${answer.correct?'correct-text':'wrong-text'}">${answer.correct?'回答正确':'这次再巩固一下'}</strong><p>${question.zh}</p><p><span class="pos">${question.pos}</span>本句中的 <strong>${question.wordId}</strong> 表示「${question.meaning}」。其他选项不符合本句语境。</p><button class="primary" data-action="quiz-next">${quiz.index===quiz.questions.length-1?'查看测验结果':'下一题'} ${icon('arrow')}</button></div>`:''}</section></div>`;
}
function reportPage(){const l=log(),quiz=l.quiz,allAnswers=[...(l.quizHistory||[]).flatMap(q=>q.answers),...(quiz?.answers||[])],answered=allAnswers.length,correct=allAnswers.filter(a=>a.correct).length;const weak=Object.entries(state.records).filter(([,r])=>r.weak).sort((a,b)=>a[1].due.localeCompare(b[1].due));const last7=Array.from({length:7},(_,i)=>addDays(today(),i-6));const max=Math.max(5,...last7.map(d=>state.days[d]?.passed.length||0));return `${pageTitle('YOUR LEARNING, IN FOCUS','一点一滴，都算数。','当天通过是一个起点，长期掌握来自持续复习。')}<div class="report-stats">${[[l.newWords.length,'今日新学 / 词'],[l.reviewWords.length,'今日复习 / 词'],[answered?Math.round(correct/answered*100)+'%':'—','测验正确率'],[allAnswers.filter(a=>a.assisted).length,'原文辅助 / 题']].map(([v,label])=>`<div class="stat"><b>${v}</b><span>${label}</span></div>`).join('')}</div><div class="report-layout"><section class="panel"><div class="section-heading"><h2>最近 7 天</h2><span class="muted">通过词义数</span></div><div class="bar-chart" role="img" aria-label="最近七天通过词义数量">${last7.map(d=>{const value=state.days[d]?.passed.length||0;return `<div class="bar-column"><span>${value}</span><div class="bar-track"><div style="height:${value/max*100}%" class="${d===today()?'current':''}"></div></div><small>${d.slice(5).replace('-','/')}</small></div>`;}).join('')}</div></section><section class="panel"><h2>记忆进展</h2><button data-action="known-list">管理完全记住的词（${Object.keys(state.knownWords||{}).length}）</button><div class="info-row"><span>今天通过的词义</span><strong>${l.passed.length}</strong></div><div class="info-row"><span>累计学过的词义</span><strong>${Object.keys(state.records).length}</strong></div><div class="info-row"><span>达到第 6 学习阶段</span><strong>${Object.values(state.records).filter(r=>r.level===6).length}</strong></div><p class="fine">只听读音认识：上次间隔 ×2.5；听语境认识：×1.6；看拼写认识：×0.8（2–7 天）；看例句认识：×0.5（1–3 天）；仍不认识：1 天。自测权重是本站启发式设计，并非精确预测记忆。</p></section></div><section class="panel"><div class="section-heading"><h2>还需要多见几次</h2><span class="pill">薄弱词义 ${weak.length}</span></div>${weak.length?`<div class="table-wrap"><table><thead><tr><th>单词</th><th>需要巩固的词义</th><th>下次复习</th><th>进度</th></tr></thead><tbody>${weak.map(([id,r])=>{const s=wordMap[r.wordId].senses.find(s=>s.id===id);return `<tr><td><strong>${r.wordId}</strong></td><td>${s.pos} ${esc(s.meaning)}</td><td>${r.due<=today()?'已到期':r.due}</td><td>第 ${r.level} 阶段</td></tr>`;}).join('')}</tbody></table></div>`:'<p class="muted">暂无薄弱词义。学习中选择“不认识”或测验答错后，会在这里记录。</p>'}</section><div class="report-actions"><button data-action="settings">备份学习数据</button><button class="primary" data-action="navigate" data-to="today">返回今日学习 ${icon('arrow')}</button></div>`;}
function render(){clearInterval(restTimer);if(!['grammar','ielts','ielts-plan','ielts-listening','ielts-writing','ielts-speaking','ielts-reading','ielts-notebook','ielts-review','today','courses','learn','reading','quiz','report'].includes(route))route='ielts';const pages={today:todayPage,courses:coursesPage,learn:learnPage,reading:readingPage,quiz:quizPage,report:reportPage};document.getElementById('app').innerHTML=header()+`<main class="main ${route==='learn'?'study-main':''}" id="main" tabindex="-1">${storageError?'<div class="warning">本地存储不可用或旧数据无法读取。请在设置中导出当前进度；原有数据尚未自动清除。</div>':''}${route==='grammar'?grammarPage():route.startsWith('ielts')?ieltsPage(route):pages[route]()}</main><footer class="site-footer"><span>词序 Lexiday</span><span>自主整理词库 · 支持账号同步</span><button class="text-button" data-action="settings">数据与说明</button></footer>`;document.title=({grammar:'语法课堂',today:'今日学习',courses:'词书课程',learn:'单词学习',reading:'今日阅读',quiz:'听力测验',report:'学习报告'}[route]||'雅思半年计划')+' · 词序 Lexiday';syncLearningAudio();}
function dialog(content){document.querySelector('dialog')?.remove();const d=document.createElement('dialog');d.innerHTML=`<div class="dialog-heading"><h2>${content.title}</h2><button class="icon-btn" data-action="close-dialog" aria-label="关闭">${icon('close')}</button></div>${content.body}`;document.body.append(d);d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});d.showModal();}
let vocabularyId='',vocabularyPage=0,vocabularyQuery='',vocabularyType='全部';
function showVocabulary(id){vocabularyId=id;vocabularyPage=0;vocabularyQuery='';vocabularyType='全部';const c=courseMap[id];if(!c)return;dialog({title:c.name+' · 词表',body:`<p>${c.words.length} 个词条。词族关联不等于同义关系；形近词按拼写识别。</p><label for="vocabulary-search">搜索英文、中文或主题</label><input id="vocabulary-search" type="search" autocomplete="off"><label for="vocabulary-type">关联分类</label><select id="vocabulary-type"><option>全部</option><option>近义词</option><option>形近词</option><option>同词族</option></select><div id="vocabulary-items"></div>`});renderVocabulary();}
function renderVocabulary(){
 const c=courseMap[vocabularyId];if(!c)return;
 const hasType=note=>vocabularyType==='全部'||(note.types||[note.type]).includes(vocabularyType);
 const list=c.words.filter(id=>{const w=wordMap[id];return [w.word,w.topic||w.group,...wordEntries(w).map(s=>s.meaning),...(importedGloss[id]||[])].join(' ').toLowerCase().includes(vocabularyQuery)&&(vocabularyType==='全部'||w.notes.some(hasType));});
 const total=Math.max(1,Math.ceil(list.length/40));vocabularyPage=Math.max(0,Math.min(vocabularyPage,total-1));
 document.getElementById('vocabulary-items').innerHTML='<p class="fine">匹配 '+list.length+' 词 · 第 '+(vocabularyPage+1)+' / '+total+' 页</p><div class="vocabulary-list">'+list.slice(vocabularyPage*40,vocabularyPage*40+40).map(id=>{
  const w=wordMap[id],entries=wordEntries(w);
  return '<details class="vocabulary-entry"><summary><strong>'+esc(w.word)+'</strong> <span class="muted">'+esc(wordPronunciation(w))+'</span><small>'+esc(entries[0]?.meaning)+'</small></summary>'+entries.map(entry=>meaningEntry(w,entry)).join('')+relationCards({...w,notes:w.notes.filter(hasType)})+'<button data-action="'+(state.knownWords?.[id]?'restore-known':'exclude-known')+'" data-id="'+esc(id)+'">'+(state.knownWords?.[id]?'恢复学习和复习':'完全记住 · 不再学习和复习')+'</button></details>';
 }).join('')+'</div><div class="vocabulary-pagination"><button data-action="vocab-prev" '+(vocabularyPage?'':'disabled')+'>上一页</button><button data-action="vocab-next" '+(vocabularyPage+1<total?'':'disabled')+'>下一页</button></div>';
}
document.addEventListener('input',event=>{
 if(event.target.id!=='meaning-answer')return;
 try{setMeaningDraft(state,event.target.value);save();}catch(error){toast(error.message);}
});
document.addEventListener('submit',event=>{
 if(event.target.id!=='meaning-answer-form')return;event.preventDefault();
 try{
  if(state.session?.day!==today()){begin(state);save();render();toast('新的一天，已重新安排今日任务。');return;}
  const input=new FormData(event.target).get('meaning');speech.stop();
  if(state.session?.stage==='listen')answerListening(state,input);else answerReviewMeaning(state,input);
  save();render();window.scrollTo({top:0,behavior:'instant'});
 }catch(error){toast(error.message);}
});
document.addEventListener('input',e=>{if(e.target.id==='vocabulary-search'){vocabularyQuery=e.target.value.trim().toLowerCase();vocabularyPage=0;renderVocabulary();}});
document.addEventListener('change',e=>{if(e.target.id==='vocabulary-type'){vocabularyType=e.target.value;vocabularyPage=0;renderVocabulary();}});
function showPlan(){dialog({title:'把学习安排得刚刚好',body:`<p class="muted">${courseMap[state.course].name} · 剩余 ${remainingWords(state).length} 个新词</p><form id="plan-form"><label for="plan-order">新词关联顺序</label><select id="plan-order" name="order">${[["source","原词表 / 主题顺序"],["meaning","近义词关联"],["spelling","形近词对比"],["family","同词族关联"]].map(([v,t])=>`<option value="${v}" ${(state.plan.order||"source")===v?"selected":""}>${t}</option>`).join("")}</select><p class="fine">有可靠关联时每组最多 5 词，不足不强行凑组。复习仍优先并打乱顺序。</p><label for="plan-mode">计划方式</label><select id="plan-mode" name="mode"><option value="count" ${state.plan.mode==='count'?'selected':''}>每天学习固定数量</option><option value="date" ${state.plan.mode==='date'?'selected':''}>按目标完成日期计算</option></select><div id="count-field" ${state.plan.mode==='date'?'hidden':''}><label for="plan-count">每天的新词数</label><input id="plan-count" name="count" type="number" min="1" max="100" required value="${state.plan.count}"></div><div id="date-field" ${state.plan.mode==='count'?'hidden':''}><label for="plan-target">目标完成日期</label><input id="plan-target" name="target" type="date" min="${today()}" value="${esc(state.plan.target||addDays(today(),6))}"></div><p class="fine">调整后会保留当前练习。新增任务将在本轮完成后按新的每日额度安排；复习数量另外计算。</p><button class="primary full-width" type="submit">保存计划</button></form>`});}
function settings(){dialog({title:'你的进度，由你保管',body:`<span class="pill">本机备份与账号同步</span><p>访客记录保存在当前浏览器。登录后，单词、语法与雅思进度自动同步到账号；可通过页面下方的账号入口查看同步状态。音频文件和临时录音不上传。</p><div class="settings-actions"><button data-action="export">导出学习备份</button><label class="file-label">导入并替换进度<input type="file" id="import-file" accept="application/json,.json"></label></div><p class="fine">导入前会要求确认。备份只含学习数据，不含密钥。</p><hr><h3>关于演示内容</h3><p class="muted">已提供 ${words.length} 个去重单词及 ${words.reduce((a,w)=>a+wordEntries(w).length,0)} 个词义，覆盖零基础、中考、高考、雅思基础和雅思进阶五本课程。上传词表补充至雅思基础，词性、释义与例句分别呈现。词库不是官方完整词表，尚未经外部词典逐条认证。每日阅读按今日词汇生成连贯文章，暂不可用时提供完整主题文章；正文覆盖率按实际出现的词计算。听力测验使用预编例句。</p><p class="muted">朗读使用浏览器和设备提供的英文语音。无可用语音时可以先看文字学习；新词仍须完成听音输入验证，才会算作通过。</p>`});}
const speech=createSpeechController({onError:()=>{
 if(route==='quiz'&&readyForExtras()){
  const quiz=log().quiz;if(quiz?.questions[quiz.index]){quiz.audioPlaying=false;quiz.audioUnavailable=true;if(!quiz.submitted)quiz.played=false;updateQuizAudioUi(quiz);}
 }

 const q=state.session;if(route==='learn'&&q?.stage==='listen')listeningUnavailable(state);
 if(route==='learn'&&q?.stage==='review'&&['audio','context'].includes(q.cue)){q.cuePlayed=false;q.audioUnavailable=true;}
 const button=document.getElementById('meaning-submit');if(button&&['listen','review'].includes(q?.stage))button.disabled=true;
 const status=document.getElementById('learning-audio-status');if(status)status.textContent='自动朗读未完成，请点击“播放 / 重播”重试。';
 toast('语音未完成播放。请点击重播，并确认设备有可用的英文语音。');save();
}});
let autoAudioKey='',autoAudioSession=null,autoAudioTask=null,autoQuizKey='',autoQuizSession=null;
function speak(text,onEnd){return speech.play(text,onEnd);}
function playLearningAudio(){
 const q=state.session;if(route!=='learn'||!q?.current)return;
 const w=wordMap[q.current.wordId],ex=activeExample(state),stage=q.stage,cue=stage==='listen'?q.listenCue:q.cue,task=q.current;
 const texts=stage==='listen'?[listeningAudio(state)]:stage==='review'?[reviewAudio(state)]:stage==='bare'?[spokenWord(w)]:['sentence','detail'].includes(stage)?[spokenWord(w),ex?.en]:[];
 if(!texts.some(Boolean))return;
 if(stage==='listen')q.listenPlayed=false;if(stage==='review')q.cuePlayed=false;
 const button=document.getElementById('meaning-submit');if(button&&['listen','review'].includes(stage))button.disabled=true;
 speak(texts,()=>{
  if(state.session!==q||q.current!==task||route!=='learn'||q.stage!==stage||(stage==='listen'?q.listenCue:q.cue)!==cue)return;
  if(stage==='listen')markListeningPlayed(state);if(stage==='review')markReviewPlayed(state);
  save();const button=document.getElementById('meaning-submit');if(button)button.disabled=false;
  const status=document.getElementById('learning-audio-status');if(status)status.textContent='已听完，可以输入中文释义。';
 });
}
function quizAudioStatus(quiz){
 if(quiz.audioUnavailable)return '自动播放未完成，请点击上方按钮重播。';
 if(quiz.audioPlaying)return quiz.submitted?'原文已显示，正在再次朗读。':'正在自动播放句子和语音问题…';
 if(quiz.submitted)return '原文已显示，可随时点击上方按钮重播。';
 return quiz.played?'已播放完毕，请选择对应的意思。':'即将自动播放句子和语音问题…';
}
function updateQuizAudioUi(quiz){
 const status=document.getElementById('quiz-audio-status');if(status)status.textContent=quizAudioStatus(quiz);
 for(const button of document.querySelectorAll('[data-action="option"]'))button.disabled=quiz.submitted||(!quiz.played&&!quiz.revealed);
}
function playQuizAudio(){
 if(route!=='quiz'||!readyForExtras())return;
 const quiz=log().quiz,question=quiz?.questions[quiz.index];if(!question)return;
 const index=quiz.index,submitted=quiz.submitted,day=today();
 if(!submitted)quiz.played=false;quiz.audioUnavailable=false;quiz.audioPlaying=true;save();updateQuizAudioUi(quiz);
 const target=spokenWord(wordMap[question.wordId]);
 speak(submitted?[question.en]:[question.en,'What does '+target+' mean in this sentence?'],()=>{
  if(route!=='quiz'||today()!==day||log().quiz!==quiz||quiz.index!==index||quiz.submitted!==submitted||quiz.questions[index]!==question)return;
  quiz.audioPlaying=false;if(!submitted)quiz.played=true;save();updateQuizAudioUi(quiz);
 });
}
function syncLearningAudio(){
 const quiz=route==='quiz'&&readyForExtras()?log().quiz:null;
 if(quiz?.questions[quiz.index]){
  const key=[today(),quiz.index,quiz.submitted?'answer':'question'].join('|');
  autoAudioKey='';autoAudioSession=null;autoAudioTask=null;
  if(autoQuizSession===quiz&&autoQuizKey===key)return;
  autoQuizSession=quiz;autoQuizKey=key;speech.stop();playQuizAudio();return;
 }
 if(autoQuizSession){speech.stop();autoQuizSession.audioPlaying=false;autoQuizSession=null;autoQuizKey='';}
 const q=state.session;
 const supported=route==='learn'&&q?.current&&(['bare','sentence','detail','listen'].includes(q.stage)||q.stage==='review'&&['audio','context'].includes(q.cue));
 const key=supported?[q.day,q.current.senseId,q.current.round,q.stage,q.stage==='listen'?q.listenCue:q.cue].join('|'):'';
 if(key===autoAudioKey&&autoAudioSession===q&&autoAudioTask===q?.current)return;
 autoAudioKey=key;autoAudioSession=q;autoAudioTask=q?.current;speech.stop();if(key)playLearningAudio();
}
window.addEventListener('pagehide',()=>speech.stop());
function start(){if(state.plan.paused){showPlan();toast('计划已暂停，请在首页恢复后开始。');return;}begin(state);save();nav('learn');}
function recordQuizOption(index){const q=log().quiz;if(!q||q.submitted||(!q.played&&!q.revealed))return;const question=q.questions[q.index];if(!Number.isInteger(index)||index<0||index>=question.options.length)throw new Error('选项无效。');const chosen=question.options[index],correct=chosen===question.meaning;q.answers.push({senseId:question.senseId,chosen,correct,assisted:q.revealed});q.submitted=true;if(!correct){const r=state.records[question.senseId];if(r&&!state.knownWords?.[r.wordId]){r.due=addDays(today(),1);r.weak=true;(state.unknownSenses??={})[question.senseId]=true;}}save();render();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action;if(['review-yes','review-no','review-text','continue','exclude-known','listen-unknown','listen-cue'].includes(action))speech.stop();try{if(['bare-yes','bare-no','sense-yes','sense-no','correct','continue','rest','review-play','review-yes','review-no','review-text','listen-play','listen-cue','listen-unknown'].includes(action)&&state.session?.day!==today()){begin(state);save();render();toast('新的一天，已重新安排今日任务。');return;}if(action==='navigate'){nav(b.dataset.to);return;}if(action==='start'){start();return;}if(action==='vocab-prev'||action==='vocab-next'){vocabularyPage+=action==='vocab-next'?1:-1;renderVocabulary();return;}if(action==='vocabulary'){showVocabulary(b.dataset.id);return;}if(action==='plan'){showPlan();return;}if(action==='settings'){settings();return;}if(action==='close-dialog'){b.closest('dialog')?.close();return;}if(action==='pause'){state.plan.paused=!state.plan.paused;save();render();toast(state.plan.paused?'计划已暂停，进度已保留。':'计划已恢复。');return;}if(action==='filter'){courseFilter=b.dataset.filter;render();return;}if(action==='course'){if(!courseMap[b.dataset.id]?.words.length)return;state.course=b.dataset.id;save();nav('today');toast('已切换词书，相同词义的进度已保留。');return;}if(action==='speak'){speak(b.dataset.text);return;}if(action==='stop-speech'){speech.stop();return;}if(action==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='lexiday-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);return;}
 if(action==='review-play'||action==='listen-play'){playLearningAudio();return;}else if(action==='listen-cue'){setListeningCue(state,b.dataset.cue);}else if(action==='listen-unknown'){answerListening(state,'',{unknown:true});}else if(action==='review-text')useReviewText(state);else if(action==='review-yes'||action==='review-no')answerReview(state,action==='review-yes');else if(action==='exclude-known'){excludeKnownWord(state,b.dataset.id);document.querySelector('dialog')?.close();}else if(action==='restore-known'){restoreKnownWord(state,b.dataset.id);save();showKnownWords();render();return;}else if(action==='known-list'){showKnownWords();return;}else if(action.startsWith('bare-'))answerBare(state,action==='bare-yes');else if(action.startsWith('sense-'))answerSense(state,action==='sense-yes');else if(action==='correct'){correctAnswer(state);toast('已改为不认识，刚才这次认识不再计数。');}else if(action==='continue'){continueLearning(state);window.scrollTo({top:0,behavior:'instant'});}else if(action==='rest')leaveRest(state);else if(action==='article'){generateDailyArticle();return;}else if(action==='translation'){translation=!translation;}else if(action==='toggle-highlight'){highlight=!highlight;}else if(action==='gloss'){selectedWord={wordId:b.dataset.id,senseId:b.dataset.sense,...(b.dataset.paragraph!==undefined?{paragraphIndex:Number(b.dataset.paragraph)}:{})};}else if(action==='quiz-start'||action==='quiz-wrong'){const nextQuiz=makeQuiz(state,log(),action==='quiz-wrong');if(log().quiz)(log().quizHistory??=[]).push(log().quiz);log().quiz=nextQuiz;}else if(action==='quiz-play'){playQuizAudio();return;}else if(action==='reveal'){const q=log().quiz;if(!q.submitted)q.revealed=true;}else if(action==='option'){recordQuizOption(Number(b.dataset.index));return;}else if(action==='quiz-next'){const q=log().quiz;if(!q.submitted)return;speech.stop();q.index++;q.submitted=false;q.revealed=false;q.played=false;q.audioPlaying=false;q.audioUnavailable=false;}else return;save();render();if(['bare-yes','bare-no','sense-yes','sense-no','rest'].includes(action))window.scrollTo({top:0,behavior:'instant'});}catch(err){toast(err.message||'操作未完成，请重试。');}});
document.addEventListener('change',async e=>{if(e.target.id==='plan-mode'){document.getElementById('count-field').hidden=e.target.value!=='count';document.getElementById('date-field').hidden=e.target.value!=='date';}if(e.target.id==='import-file'){const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw new Error('文件过大，请选择有效学习备份。');const imported=validateState(JSON.parse(await f.text()));if(!confirm('导入将替换当前浏览器的全部学习进度，是否继续？'))return;state=imported;storageError=false;save();document.querySelector('dialog')?.close();render();toast('学习进度已恢复。');}catch(err){toast(err.message||'无法读取此备份。');}e.target.value='';}});
document.addEventListener('submit',e=>{if(e.target.id!=='plan-form')return;e.preventDefault();const f=new FormData(e.target);const count=Number(f.get('count')),mode=f.get('mode'),target=f.get('target');if(!Number.isInteger(count)||count<1||count>100){toast('每日数量需为 1–100 的整数。');return;}if(mode==='date'&&(!/^\d{4}-\d{2}-\d{2}$/.test(target)||target<today())){toast('请选择今天或之后的完成日期。');return;}state.plan={...state.plan,count,mode,target,order:f.get('order')||'source'};save();e.target.closest('dialog').close();render();toast('计划已保存，已有进度会保留。');});
initIelts({toast,render});
initGrammar({toast,render});
render();
// Optional WebMCP: all actions use the same state and UI functions as visitor controls.
const context=document.modelContext;const lifecycle=new AbortController();
if(context?.registerTool){const tools=[{name:'read_learning_progress',description:'Read the visitor’s current local learning progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({course:state.course,stats:dailyStats(state),stage:state.session?.stage||null})},{name:'configure_daily_word_count',description:'Set the daily new-word target from 1 to 100, preserving current progress.',inputSchema:{type:'object',properties:{count:{type:'integer',minimum:1,maximum:100}},required:['count'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({count})=>{if(!Number.isInteger(count)||count<1||count>100)throw new Error('count must be an integer from 1 to 100');state.plan={...state.plan,mode:'count',count};save();render();return {count};}},{name:'start_learning_session',description:'Start or resume the current learning session; does not answer or mark words as known.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:()=>{if(state.plan.paused)throw new Error('The plan is paused');start();return {stage:state.session.stage};}}];for(const t of tools)try{Promise.resolve(context.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

function reviewCard(q,w,se,ex){
 const titles={audio:'只听单词，输入中文意思',context:'听带单词的例句，输入中文意思',spelling:'看拼写辅助回想',sentence:'看例句辅助回想'},listening=['audio','context'].includes(q.cue);
 return '<section class="panel recall-card"><span class="pill">到期复习 · 输入验证</span><h2>'+titles[q.cue]+'</h2>'+(listening?'<button class="primary review-speaker" data-action="review-play">'+icon('sound')+' 播放 / 重播</button><p>拼写和释义暂不显示，请输入你听到的含义。</p><p id="learning-audio-status" role="status">'+(q.cuePlayed?'已听完，可以输入中文释义。':'正在自动播放。')+'</p><button class="text-button" data-action="review-text">音频不可用，先用文字学习</button>':'<div class="bare-word">'+esc(w.word)+'</div>'+(q.cue==='sentence'&&ex?'<p class="example-sentence">'+highlightWord(ex.en,w.id)+'</p>'+speakButton(ex.en,'听例句'):'')+'<p class="fine">已记录文字辅助。尚未完成首次听音验证的词，会继续安排听音复习。</p>')+(q.meaningFeedback?'<p class="warning" role="status">'+esc(q.meaningFeedback)+'</p>':'')+meaningForm(q,!listening||q.cuePlayed)+'<button class="text-button" data-action="review-no">没听懂 / 不知道'+(q.cue==='sentence'?'，查看释义':'，下一步提示')+'</button></section>';
}
function relationCards(w){return '<div class="relation-grid">'+deduplicateNotes(w.notes).map(n=>{
 const related=wordMap[n.word]||{id:n.word,word:n.word,ipa:'',senses:[{pos:'词条',meaning:n.meaning,examples:[]}]};
 const entries=wordEntries(related),types=n.types||[n.type];
 const comparisons=(n.differences||[n.difference]).filter(text=>text&&!text.startsWith('同词族词汇，注意派生形式'));
 return '<article class="relation-card" data-note-word="'+esc(n.word.toLowerCase())+'"><div class="relation-card-heading"><strong>'+esc(n.word)+'</strong>'+types.map(type=>'<span class="relation-type '+(type==='形近词'?'shape':type==='同词族'?'family':'meaning')+'">'+esc(type)+'</span>').join('')+'</div>'+comparisons.map(text=>'<p class="fine">区别对比：'+esc(text)+'</p>').join('')+'<details open><summary>词性、释义与例句 · '+entries.length+' 个义项</summary>'+entries.map(entry=>meaningEntry(related,entry)).join('')+'</details></article>';
}).join('')+'</div>';}
function showKnownWords(){const ids=Object.keys(state.knownWords||{});dialog({title:'完全记住的词 · 不进入复习队列',body:`<p>这是主动排除标记，不是自动判定永久掌握。可随时恢复，恢复后将重新安排复习。</p>${ids.length?ids.map(id=>`<p><strong>${esc(wordMap[id].word)}</strong> <button data-action="restore-known" data-id="${esc(id)}">恢复复习</button></p>`).join(''):'<p class="muted">还没有标记的单词。</p>'}`});}
